		case '\'':
			if ch == '\'' {
				quote = 0
			}
		case '"':
			if escaped {
				escaped = false
			} else if ch == '\\' {
				escaped = true
			} else if ch == '"' {
				quote = 0
			}
		default:
			if ch == '\'' || ch == '"' {
				quote = ch
			} else if ch == '\\' {
				i++
			}
		}
	}
	if quote == 0 {
		return ""
