func (failingSpeechRuntime) Synthesize(context.Context, speechtts.Request) (speechtts.Result, error) {
	return speechtts.Result{}, &speechtts.Error{Code: speechtts.ErrorCodeInvalidInput, Message: "unsupported text"}
}

